// 与 floppy-blueprint.html 中一致的 Shape 构建逻辑，验证三角化/挤出无误
import * as THREE from './three.module.js';

let pass = 0, fail = 0;
function check(name, fn) {
  try {
    fn();
    console.log('PASS:', name);
    pass++;
  } catch (e) {
    console.log('FAIL:', name, '->', e.message);
    fail++;
  }
}

const HEAD_CHANNEL = { cx: -6, cz: 22.5, w: 6, d: 14 };

function roundedRectShape(hw, hh, r) {
  const s = new THREE.Shape();
  const x0 = -hw, y0 = -hh, x1 = hw, y1 = hh;
  s.moveTo(x0 + r, y0);
  s.lineTo(x1 - r, y0);
  s.absarc(x1 - r, y0 + r, r, -Math.PI / 2, 0, false);
  s.lineTo(x1, y1 - r);
  s.absarc(x1 - r, y1 - r, r, 0, Math.PI / 2, false);
  s.lineTo(x0 + r, y1);
  s.absarc(x0 + r, y1 - r, r, Math.PI / 2, Math.PI, false);
  s.lineTo(x0, y0 + r);
  s.absarc(x0 + r, y0 + r, r, Math.PI, Math.PI * 1.5, false);
  return s;
}
function addRectHole(shape, cx, cz, w, d) {
  const p = new THREE.Path();
  const x0 = cx - w / 2, x1 = cx + w / 2;
  const z0 = cz - d / 2, z1 = cz + d / 2;
  p.moveTo(x0, -z0);
  p.lineTo(x0, -z1);
  p.lineTo(x1, -z1);
  p.lineTo(x1, -z0);
  p.closePath();
  shape.holes.push(p);
}
function addCircleHole(shape, cx, cz, r) {
  const p = new THREE.Path();
  p.absarc(cx, -cz, r, 0, Math.PI * 2, true);
  shape.holes.push(p);
}

// 1) TOP SHELL 形状（4 个真实孔）
check('top shell shape triangulates', () => {
  const s = roundedRectShape(30, 30, 3);
  addRectHole(s, -25.5, -25.5, 4, 4);
  addRectHole(s, HEAD_CHANNEL.cx, HEAD_CHANNEL.cz, HEAD_CHANNEL.w, HEAD_CHANNEL.d);
  addRectHole(s, 0, -17, 36, 22);
  addRectHole(s, 0, 7, 20, 10);
  const g = new THREE.ExtrudeGeometry(s, { depth: 2, bevelEnabled: false, curveSegments: 24 });
  g.translate(0, 0, -1);
  g.rotateX(-Math.PI / 2);
  if (g.getAttribute('position').count < 100) throw new Error('too few vertices');
  // 检查孔边缘存在：世界 Z 方向的极值应在 ±30 附近，且孔壁在 z≈29.5 存在
  let maxZ = -1e9, minZ = 1e9;
  const pos = g.getAttribute('position');
  for (let i = 0; i < pos.count; i++) {
    maxZ = Math.max(maxZ, pos.getZ(i));
    minZ = Math.min(minZ, pos.getZ(i));
  }
  if (Math.abs(maxZ - 30) > 1e-6) throw new Error('maxZ=' + maxZ);
  if (Math.abs(minZ + 30) > 1e-6) throw new Error('minZ=' + minZ);
});

// 2) BOTTOM SHELL 形状（槽孔 + 中央圆孔 + 防写凹口）
check('bottom shell shape triangulates', () => {
  const s = roundedRectShape(30, 30, 3);
  addRectHole(s, HEAD_CHANNEL.cx, HEAD_CHANNEL.cz, HEAD_CHANNEL.w, HEAD_CHANNEL.d);
  addCircleHole(s, 0, 0, 7);
  addRectHole(s, 25.5, -25.5, 3, 3);
  const g = new THREE.ExtrudeGeometry(s, { depth: 2, bevelEnabled: false, curveSegments: 24 });
  if (g.getAttribute('position').count < 100) throw new Error('too few vertices');
});

// 3) DUST LINER：C 形圆环 + 矩形缺口
function dustLinerShape() {
  const R = 26.5, rIn = 9;
  const xA = -11, xB = -1, sInner = -12;
  const sA = -Math.sqrt(R * R - xA * xA);
  const sB = -Math.sqrt(R * R - xB * xB);
  const thA = Math.atan2(sA, xA), thB = Math.atan2(sB, xB);
  const s = new THREE.Shape();
  s.moveTo(xA, sA);
  s.lineTo(xA, sInner);
  s.lineTo(xB, sInner);
  s.lineTo(xB, sB);
  s.absarc(0, 0, R, thB, thA + Math.PI * 2, false);
  s.closePath();
  addCircleHole(s, 0, 0, rIn);
  return s;
}
check('dust liner shape triangulates', () => {
  const g = new THREE.ExtrudeGeometry(dustLinerShape(), { depth: 0.06, bevelEnabled: false, curveSegments: 24 });
  if (g.getAttribute('position').count < 100) throw new Error('too few vertices');
});
// 验证 liner 缺口真实存在：形状在缺口区（世界 x=-6, z=15.5..26.5）不应覆盖
check('dust liner notch is a real bite (point-in-polygon)', () => {
  const s = dustLinerShape();
  const pts = s.getPoints(200);
  // 世界点 (x, z) -> shape (x, -z)
  const inside = (x, z) => {
    const px = x, py = -z;
    let inPoly = false;
    for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) {
      const xi = pts[i].x, yi = pts[i].y, xj = pts[j].x, yj = pts[j].y;
      if ((yi > py) !== (yj > py) && px < ((xj - xi) * (py - yi)) / (yj - yi) + xi) inPoly = !inPoly;
    }
    return inPoly;
  };
  if (inside(-6, 20)) throw new Error('notch region (-6,20) should be REMOVED');
  if (!inside(-6, 5)) throw new Error('inner-hole region: point (-6,5) is inside inner hole too — expected outside');
  if (!inside(-6, -20)) throw new Error('body region (-6,-20) should be INSIDE');
  if (!inside(-20, 0)) throw new Error('left region should be INSIDE');
  if (inside(0, 26.4)) throw new Error('tip (0,26.4) x=0 outside bite range but on circle… check expected');
});

// 4) BOTTOM SHELL 大圆凹陷叠加盘（圆 + 磁头通道缺口 + 中央孔）
check('recess overlay shape triangulates', () => {
  const R = 22;
  const xL = HEAD_CHANNEL.cx - HEAD_CHANNEL.w / 2;
  const xR = HEAD_CHANNEL.cx + HEAD_CHANNEL.w / 2;
  const sTop = -(HEAD_CHANNEL.cz - HEAD_CHANNEL.d / 2);
  const sL = -Math.sqrt(R * R - xL * xL);
  const sR = -Math.sqrt(R * R - xR * xR);
  const thL = Math.atan2(sL, xL), thR = Math.atan2(sR, xR);
  const s = new THREE.Shape();
  s.moveTo(xL, sL);
  s.lineTo(xL, sTop);
  s.lineTo(xR, sTop);
  s.lineTo(xR, sR);
  s.absarc(0, 0, R, thR, thL + Math.PI * 2, false);
  s.closePath();
  addCircleHole(s, 0, 0, 7);
  const g = new THREE.ExtrudeGeometry(s, { depth: 0.15, bevelEnabled: false, curveSegments: 24 });
  if (g.getAttribute('position').count < 50) throw new Error('too few vertices');
});

// 5) SHUTTER 形状（矩形板 + 偏左矩形孔）
check('shutter shape triangulates', () => {
  const s = new THREE.Shape();
  s.moveTo(-11, -8); s.lineTo(11, -8); s.lineTo(11, 8); s.lineTo(-11, 8);
  s.closePath();
  const localCz = HEAD_CHANNEL.cz - 21.85;
  addRectHole(s, HEAD_CHANNEL.cx, localCz, HEAD_CHANNEL.w + 0.3, HEAD_CHANNEL.d + 0.3);
  const g = new THREE.ExtrudeGeometry(s, { depth: 1, bevelEnabled: false });
  g.translate(0, 0, -0.5);
  g.rotateX(-Math.PI / 2);
  if (g.getAttribute('position').count < 50) throw new Error('too few vertices');
});

// 6) 组装态三孔对齐验证（世界坐标）
check('assembled: top/bottom/shutter head-channel holes align', () => {
  // 快门组：SHUTTER_ASSEMBLED (0,-1.5,21.85)，孔局部中心 (cx, 0.65)
  const shutterHoleWorld = {
    cx: HEAD_CHANNEL.cx, cz: 21.85 + (HEAD_CHANNEL.cz - 21.85),
  };
  if (Math.abs(shutterHoleWorld.cx - HEAD_CHANNEL.cx) > 1e-9) throw new Error('cx mismatch');
  if (Math.abs(shutterHoleWorld.cz - HEAD_CHANNEL.cz) > 1e-9) throw new Error('cz mismatch');
});

// 7) EdgesGeometry 对圆柱与挤出几何可用
check('edges geometry builds', () => {
  const cyl = new THREE.CylinderGeometry(22, 22, 0.3, 64);
  const e1 = new THREE.EdgesGeometry(cyl, 20);
  if (e1.getAttribute('position').count < 100) throw new Error('disk edges missing');
  const box = new THREE.BoxGeometry(8, 0.92, 4);
  const e2 = new THREE.EdgesGeometry(box, 20);
  if (e2.getAttribute('position').count < 24) throw new Error('box edges missing');
});

console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);

