content.text:
完成。文件已写入 `floppy-blueprint.html`，并通过了 Node 端的三.js 几何验证（8/8 通过：所有 `Shape + holes` 三角化、防尘布缺口点测试、三处磁头通道同轴对齐、EdgesGeometry 构建）。核心实现要点：

- **蓝图风格**：`#F5F7FA` + Canvas 点阵背景；正交相机 `(100,80,100)` 等距视角；全 `#4169E1` 工程蓝 `EdgesGeometry` 线框；爆炸态填充 `opacity 0.08`（磁片 `0.5`），组装态全部回到 1。
- **SHUTTER**：不透明 `#4A5568` 金属板 + 真实矩形镂空（偏左、短边 ∥ 长边），不参与任何透明度动画。
- **三处磁头通道**：TOP/BOTTOM/SHUTTER 共用 `HEAD_CHANNEL` 常量生成孔洞，组装态同轴对齐（快门孔名义 6×14、各边内缩 0.15 仅防共面闪烁，注释中已说明）。
- **动画**：`assembled → exploding → exploded → collapsing` 状态机，空格切换；3 秒总时长、手写 `easeInOutCubic`、80ms 自上而下错峰，位置与材质透明度共用同一 progress 插值；虚线 0.2s、标签每 60ms 逐个淡入，收回时先淡出标注再合体。
- **交互**：OrbitControls 显式设置左键旋转/中键 Dolly/右键平移（滚轮始终可用），`contextmenu` 屏蔽，`minZoom/maxZoom` + 平移钳制，底部呼吸提示 + 操作说明小字。

完整代码如下：

```html
<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
<title>FIG_001 — 3.5&quot; FLOPPY DISK · EXPLODED BLUEPRINT</title>
<style>
  /* ============ 页面与蓝图底色（浅灰白 + 点阵网格） ============ */
  html, body {
    margin: 0; padding: 0;
    width: 100%; height: 100%;
    overflow: hidden;
    background: #F5F7FA;
    font-family: 'Courier New', Courier, monospace;
  }
  #dotgrid { position: fixed; inset: 0; z-index: 0; display: block; }

  /* ============ 画面左右垂直标题 ============ */
  #fig001 {
    position: fixed; left: 30px; top: 50%;
    transform: translateY(-50%);
    z-index: 3; color: #4169E1; opacity: 0.6;
    font-size: 15px; letter-spacing: 0.45em;
    writing-mode: vertical-rl;           /* 垂直排版 */
    user-select: none; pointer-events: none;
  }
  #figtitle {
    position: fixed; right: 30px; top: 50%;
    transform: translateY(-50%);
    z-index: 3; color: #4169E1; opacity: 0.6;
    font-size: 13px; letter-spacing: 0.3em;
    writing-mode: vertical-rl;
    user-select: none; pointer-events: none;
  }

  /* ============ 底部提示 UI ============ */
  #hint {
    position: fixed; left: 50%; bottom: 42px;
    transform: translateX(-50%);
    z-index: 3; color: #4169E1;
    font-size: 13px; letter-spacing: 2px; white-space: nowrap;
    opacity: 1; transition: opacity 0.5s ease;
    pointer-events: none;
  }
  #hint .breathe { animation: breathe 2.6s ease-in-out infinite; }
  @keyframes breathe {
    0%, 100% { opacity: 0.35; }
    50%      { opacity: 0.80; }
  }
  #controlsHint {
    position: fixed; left: 50%; bottom: 16px;
    transform: translateX(-50%);
    z-index: 3; color: #4169E1; opacity: 0.45;
    font-size: 10px; letter-spacing: 1.5px; white-space: nowrap;
    pointer-events: none;
  }

  /* ============ CSS2D 标注 ============ */
  .floppy-label {
    font-family: 'Courier New', Courier, monospace;
    font-size: 12px; color: #4169E1;
    white-space: nowrap; letter-spacing: 0.5px;
    opacity: 0; transition: opacity 0.4s ease;
    pointer-events: none; user-select: none;
  }
</style>
</head>
<body>

<!-- 背景点阵网格 Canvas -->
<canvas id="dotgrid"></canvas>

<!-- 画面装饰：左侧 FIG_001 / 右侧标题（HTML 绝对定位，垂直排版） -->
<div id="fig001">FIG_001</div>
<div id="figtitle">[ 3.5&quot; FLOPPY DISK ]</div>

<!-- 底部提示：主提示 + 操作方式小字 -->
<div id="hint"><span class="breathe">PRESS [ SPACE ] TO EXPLODE</span></div>
<div id="controlsHint">LMB: ORBIT &middot; WHEEL: ZOOM &middot; RMB: PAN</div>

<script type="importmap">
{
  "imports": {
    "three": "https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.160.0/examples/jsm/"
  }
}
</script>

<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { CSS2DRenderer, CSS2DObject } from 'three/addons/renderers/CSS2DRenderer.js';

/* ================================================================
 *  常量
 * ================================================================ */
const BLUEPRINT_BLUE        = 0x4169E1;  // 工程蓝（所有线条）
const FILL_COLOR            = 0xEAF0FF;  // 蓝白半透明填充色
const DISK_COLOR            = 0x7B9DF8;  // 磁片实体蓝
const DISK_EDGE_COLOR       = 0x1D4ED8;  // 磁片深蓝描边
const SHUTTER_COLOR         = 0x4A5568;  // 快门不透明金属（深蓝灰）
const FILL_EXPLODED_OPACITY = 0.08;      // 爆炸态通用填充透明度
const DISK_EXPLODED_OPACITY = 0.50;      // 爆炸态磁片透明度

/* 磁头通道（三处共用同一组参数：TOP SHELL (d) / BOTTOM SHELL (g) / SHUTTER）
 * 位于前边缘（Z=+30）一侧，靠左（cx=-6），与参考图一致略偏一侧。
 * 注意：世界坐标中 短边 w=6 平行快门长边(X)，长边 d=14 平行快门短边(Z)。 */
const HEAD_CHANNEL = { cx: -6, cz: 22.5, w: 6, d: 14 };

const V3 = (x, y, z) => new THREE.Vector3(x, y, z);
const clamp01 = (x) => Math.max(0, Math.min(1, x));

/* 快门 / 防写滑块在组装态与爆炸态的位置（X/Z 也参与动画插值） */
const SHUTTER_ASSEMBLED = V3(0, -1.5, 21.85);
const TAB_ASSEMBLED     = V3(25.5, -0.95, -25.5);
const SHUTTER_EXPLODED  = V3(-30, -15, 30);
const TAB_EXPLODED      = V3(32, -15, -32);

/* 手写 easeInOutCubic 缓动（不依赖外部库） */
function easeInOutCubic(x) {
  x = clamp01(x);
  return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
}

/* ================================================================
 *  渲染器 / 正交相机 / 背景点阵
 * ================================================================ */
const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
renderer.setClearColor(0x000000, 0);                       // 透明，露出点阵背景
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.domElement.style.position = 'fixed';
renderer.domElement.style.inset = '0';
renderer.domElement.style.zIndex = '1';
document.body.appendChild(renderer.domElement);

/* 正交相机：等距视角 (100, 80, 100) -> lookAt(0,0,0) */
const camera = new THREE.OrthographicCamera(-100, 100, 100, -100, 0.1, 2000);
camera.position.set(100, 80, 100);
camera.lookAt(0, 0, 0);
camera.zoom = 1.1;
camera.updateProjectionMatrix();

function syncCameraAspect() {
  const aspect = Math.max(window.innerWidth / window.innerHeight, 0.5);
  camera.left = -100 * aspect;
  camera.right = 100 * aspect;
  camera.top = 100;
  camera.bottom = -100;
  camera.updateProjectionMatrix();
}
syncCameraAspect();

const cssRenderer = new CSS2DRenderer();
cssRenderer.setSize(window.innerWidth, window.innerHeight);
cssRenderer.domElement.style.position = 'fixed';
cssRenderer.domElement.style.top = '0';
cssRenderer.domElement.style.left = '0';
cssRenderer.domElement.style.zIndex = '2';
cssRenderer.domElement.style.pointerEvents = 'none';       // 不阻挡 OrbitControls
document.body.appendChild(cssRenderer.domElement);

/* 点阵网格背景（Dot Grid） */
const dotCanvas = document.getElementById('dotgrid');
function drawDotGrid() {
  const dpr = window.devicePixelRatio || 1;
  dotCanvas.width = window.innerWidth * dpr;
  dotCanvas.height = window.innerHeight * dpr;
  dotCanvas.style.width = window.innerWidth + 'px';
  dotCanvas.style.height = window.innerHeight + 'px';
  const ctx = dotCanvas.getContext('2d');
  ctx.scale(dpr, dpr);
  ctx.fillStyle = '#F5F7FA';
  ctx.fillRect(0, 0, window.innerWidth, window.innerHeight);
  ctx.fillStyle = 'rgba(65, 105, 225, 0.16)';
  const step = 26;
  for (let x = step / 2; x < window.innerWidth; x += step) {
    for (let y = step / 2; y < window.innerHeight; y += step) {
      ctx.beginPath();
      ctx.arc(x, y, 1.2, 0, Math.PI * 2);
      ctx.fill();
    }
  }
}
drawDotGrid();

window.addEventListener('resize', () => {
  syncCameraAspect();
  renderer.setSize(window.innerWidth, window.innerHeight);
  cssRenderer.setSize(window.innerWidth, window.innerHeight);
  drawDotGrid();
});

/* ================================================================
 *  通用材质与几何工具
 * ================================================================ */

/* 可淡出的半透明填充材质：组装态 opacity=1（不透明），
 * 爆炸态目标 0.08 / 0.5（由动画统一 lerp）。
 * depthWrite=false 避免近乎透明的填充错误遮挡后方线框。
 * polygonOffset 把面片在深度上后移，让同位置的 EdgesGeometry 线条浮在面上。 */
function fillMaterial(color = FILL_COLOR) {
  return new THREE.MeshBasicMaterial({
    color,
    transparent: true,
    opacity: 1,
    side: THREE.DoubleSide,
    depthWrite: false,
    polygonOffset: true,
    polygonOffsetFactor: 1,
    polygonOffsetUnits: 1,
  });
}

const edgeMat = new THREE.LineBasicMaterial({ color: BLUEPRINT_BLUE });
const lineMatSolid = new THREE.LineBasicMaterial({ color: BLUEPRINT_BLUE });

/* 在 Group 上叠加 EdgesGeometry 描边（threshold 20° 过滤圆弧侧壁的细碎线段） */
function addEdges(parent, geometry, mat = edgeMat, thresholdAngle = 20) {
  const line = new THREE.LineSegments(
    new THREE.EdgesGeometry(geometry, thresholdAngle), mat
  );
  parent.add(line);
  return line;
}

/* 圆角矩形（shape 空间，CCW），四角倒角 r */
function roundedRectShape(hw, hh, cornerR) {
  const s = new THREE.Shape();
  const x0 = -hw, y0 = -hh, x1 = hw, y1 = hh;
  s.moveTo(x0 + cornerR, y0);
  s.lineTo(x1 - cornerR, y0);
  s.absarc(x1 - cornerR, y0 + cornerR, cornerR, -Math.PI / 2, 0, false);
  s.lineTo(x1, y1 - cornerR);
  s.absarc(x1 - cornerR, y1 - cornerR, cornerR, 0, Math.PI / 2, false);
  s.lineTo(x0 + cornerR, y1);
  s.absarc(x0 + cornerR, y1 - cornerR, cornerR, Math.PI / 2, Math.PI, false);
  s.lineTo(x0, y0 + cornerR);
  s.absarc(x0 + cornerR, y0 + cornerR, cornerR, Math.PI, Math.PI * 1.5, false);
  return s;
}

/* 世界 XZ 矩形孔 → shape 空间（shape.y = -worldZ），顺时针（与外轮廓 CCW 相反） */
function rectHole(path, cx, cz, w, d) {
  const x0 = cx - w / 2, x1 = cx + w / 2;
  const z0 = cz - d / 2, z1 = cz + d / 2;
  path.moveTo(x0, -z0);
  path.lineTo(x0, -z1);
  path.lineTo(x1, -z1);
  path.lineTo(x1, -z0);
  path.closePath();
}
function addRectHole(shape, cx, cz, w, d) {
  const p = new THREE.Path();
  rectHole(p, cx, cz, w, d);
  shape.holes.push(p);
}
function addCircleHole(shape, cx, cz, r) {
  const p = new THREE.Path();
  p.absarc(cx, -cz, r, 0, Math.PI * 2, true);
  shape.holes.push(p);
}

/* 挤出 → 绕 X 轴旋转躺平（挤出方向变成世界 Y）→ 可选垂直居中 */
function extrudeFlat(shape, depth, center = true) {
  const geo = new THREE.ExtrudeGeometry(shape, {
    depth, bevelEnabled: false, curveSegments: 24,
  });
  if (center) geo.translate(0, 0, -depth / 2);
  geo.rotateX(-Math.PI / 2);
  return geo;
}

/* ================================================================
 *  3.1 TOP SHELL（上壳）—— 复合结构
 * ================================================================ */
function createTopShell() {
  const g = new THREE.Group();
  const fill = fillMaterial();

  /* 主体：60×60 倒角 3，厚度 2（局部 y ∈ [-1,1]）。
   * 真实镂空（Shape holes）：
   *  (a) HD NOTCH 左上角 4×4
   *  (d) 快门开口槽（与 HEAD_CHANNEL 共用参数，贯穿磁头通道）
   *  (b) 标签凹槽下沉区 36×22
   *  (c) 内部凹槽下沉区 20×10  */
  const shape = roundedRectShape(30, 30, 3);
  addRectHole(shape, -25.5, -25.5, 4, 4);                                  // (a)
  addRectHole(shape, HEAD_CHANNEL.cx, HEAD_CHANNEL.cz,
              HEAD_CHANNEL.w, HEAD_CHANNEL.d);                             // (d)
  addRectHole(shape, 0, -17, 36, 22);                                      // (b)
  addRectHole(shape, 0, 7, 20, 10);                                        // (c)
  const bodyGeo = extrudeFlat(shape, 2);
  g.add(new THREE.Mesh(bodyGeo, fill));
  addEdges(g, bodyGeo);

  /* (b)(c) 凹槽底板：填满孔道、顶面比上表面低 0.15 → 真实“下沉的浅凹槽”。
   * 底板尺寸内缩 0.02，避免与孔道壁共面闪烁。 */
  const mkFloor = (w, d, cz) => {
    const geo = new THREE.BoxGeometry(w, 1.84, d);
    const m = new THREE.Mesh(geo, fill);
    m.position.set(0, 1 - 0.15 - 1.84 / 2, cz);   // 顶面 y = 0.85
    g.add(m);
    addEdges(g, geo);
    return m;
  };
  mkFloor(35.96, 21.96, -17);   // (b) 标签凹槽底板
  mkFloor(19.96, 9.96, 7);      // (c) 内部凹槽底板

  /* (e) 箭头标记：位于快门开口附近，指向磁头通道 */
  const ay = 1.03;
  const stem = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([V3(-4.5, ay, 9.0), V3(-4.5, ay, 11.6)]),
    lineMatSolid
  );
  const head = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([
      V3(-6.4, ay, 11.0), V3(-4.5, ay, 14.2),
      V3(-2.6, ay, 11.0), V3(-6.4, ay, 11.0),
    ]),
    lineMatSolid
  );
  g.add(stem, head);

  return { group: g, fill };
}

/* ================================================================
 *  3.2 / 3.5 DUST LINER（防尘布）—— C 形圆环 + 矩形磁头缺口
 * ================================================================ */
function createDustLiner() {
  const g = new THREE.Group();
  const fill = fillMaterial();

  const R = 26.5, rIn = 9;
  /* 磁头窗口缺口：世界 X ∈ [-11,-1]、Z ∈ [12, 26.5]，覆盖快门通道区 */
  const xA = -11, xB = -1, sInner = -12;                  // sInner = -Z(12)
  const sA = -Math.sqrt(R * R - xA * xA);                 // 圆在 x=-11 处
  const sB = -Math.sqrt(R * R - xB * xB);                 // 圆在 x=-1  处
  const thA = Math.atan2(sA, xA), thB = Math.atan2(sB, xB);

  const s = new THREE.Shape();
  s.moveTo(xA, sA);
  s.lineTo(xA, sInner);                                   // 缺口左壁
  s.lineTo(xB, sInner);                                   // 缺口内缘
  s.lineTo(xB, sB);                                       // 缺口右壁
  s.absarc(0, 0, R, thB, thA + Math.PI * 2, false);       // 保留的长弧（CCW 绕大圈）
  s.closePath();
  addCircleHole(s, 0, 0, rIn);

  const geo = extrudeFlat(s, 0.06);                       // 极薄挤压
  g.add(new THREE.Mesh(geo, fill));
  addEdges(g, geo);
  return { group: g, fill };
}

/* ================================================================
 *  3.3 MAGNETIC DISK（磁片）—— 唯一实体填充部件
 * ================================================================ */
function createDisk() {
  const g = new THREE.Group();
  const fill = new THREE.MeshBasicMaterial({
    color: DISK_COLOR,
    transparent: true,
    opacity: 1,
    side: THREE.DoubleSide,
    depthWrite: false,
    polygonOffset: true,
    polygonOffsetFactor: 1,
    polygonOffsetUnits: 1,
  });
  const geo = new THREE.CylinderGeometry(22, 22, 0.3, 64);
  g.add(new THREE.Mesh(geo, fill));
  addEdges(g, geo, new THREE.LineBasicMaterial({ color: DISK_EDGE_COLOR }));

  /* 表面数据轨道反光斜线 */
  const ref = new THREE.LineBasicMaterial({ color: DISK_EDGE_COLOR });
  [
    [V3(-6, 0.16, 14), V3(-2, 0.16, 10)],
    [V3(4, 0.16, -12), V3(8, 0.16, -16)],
    [V3(-14, 0.16, -8), V3(-10, 0.16, -12)],
  ].forEach(([a, b]) => {
    g.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([a, b]), ref));
  });
  return { group: g, fill };
}

/* ================================================================
 *  3.4 HUB（中心金属盘）—— 中央小圆孔 + 旁边方形孔（主轴卡口）
 * ================================================================ */
function createHub() {
  const g = new THREE.Group();
  const fill = fillMaterial();

  const geo = new THREE.CylinderGeometry(5, 5, 0.36, 32);
  g.add(new THREE.Mesh(geo, fill));
  addEdges(g, geo);

  /* 中央圆形卡口孔（叠加小圆柱表示） */
  const cGeo = new THREE.CylinderGeometry(2.2, 2.2, 0.08, 20);
  const c = new THREE.Mesh(cGeo, fill);
  c.position.set(0, 0.22, 0);
  g.add(c); addEdges(g, cGeo);

  /* 旁边方形卡口孔 */
  const sGeo = new THREE.BoxGeometry(2, 0.08, 2);
  const sq = new THREE.Mesh(sGeo, fill);
  sq.position.set(3.3, 0.22, 0);
  g.add(sq); addEdges(g, sGeo);

  return { group: g, fill };
}

/* ================================================================
 *  3.6 BOTTOM SHELL（下壳）—— 复合结构
 * ================================================================ */
function createBottomShell() {
  const g = new THREE.Group();
  const fill = fillMaterial();

  /* 主体 + 真实镂空：
   *  (g) 快门开口槽（与上壳/快门同参）
   *  (b) 中央圆孔 直径 14（主轴穿孔）
   *  (f) WRITE PROTECT NOTCH 3×3（右后角） */
  const shape = roundedRectShape(30, 30, 3);
  addRectHole(shape, HEAD_CHANNEL.cx, HEAD_CHANNEL.cz,
              HEAD_CHANNEL.w, HEAD_CHANNEL.d);
  addCircleHole(shape, 0, 0, 7);
  addRectHole(shape, 25.5, -25.5, 3, 3);
  const bodyGeo = extrudeFlat(shape, 2);
  g.add(new THREE.Mesh(bodyGeo, fill));
  addEdges(g, bodyGeo);

  /* (a) 中央大圆凹陷（直径 44）：圆盘叠加在上表面，
   *     前缘处按 HEAD_CHANNEL 切出矩形缺口，与主体开口贯通，
   *     中央再开直径 14 圆孔与主体孔对齐。 */
  {
    const R = 22;
    const xL = HEAD_CHANNEL.cx - HEAD_CHANNEL.w / 2;   // -9
    const xR = HEAD_CHANNEL.cx + HEAD_CHANNEL.w / 2;   // -3
    const sTop = -(HEAD_CHANNEL.cz - HEAD_CHANNEL.d / 2);   // -15.5
    const sL = -Math.sqrt(R * R - xL * xL);
    const sR = -Math.sqrt(R * R - xR * xR);
    const thL = Math.atan2(sL, xL), thR = Math.atan2(sR, xR);

    const s = new THREE.Shape();
    s.moveTo(xL, sL);
    s.lineTo(xL, sTop);                                  // 缺口左壁
    s.lineTo(xR, sTop);                                  // 缺口内缘
    s.lineTo(xR, sR);                                    // 缺口右壁
    s.absarc(0, 0, R, thR, thL + Math.PI * 2, false);    // 保留长弧（CCW）
    s.closePath();
    addCircleHole(s, 0, 0, 7);

    const geo = extrudeFlat(s, 0.15, false);
    geo.translate(0, 1.02, 0);                           // 浮于上表面 y=1 之上 0.02
    g.add(new THREE.Mesh(geo, fill));
    addEdges(g, geo);
  }

  /* (c) 四角定位柱（半径 1.5，高约 1） */
  [[22, 22], [22, -22], [-22, 22], [-22, -22]].forEach(([x, z]) => {
    const geo = new THREE.CylinderGeometry(1.5, 1.5, 0.92, 24);
    const m = new THREE.Mesh(geo, fill);
    m.position.set(x, 1.48, z);                          // y ∈ [1.02, 1.94]
    g.add(m);
    addEdges(g, geo);
  });

  /* (d) LIFTER（8 × 4 × 1，中下方） */
  {
    const geo = new THREE.BoxGeometry(8, 0.92, 4);
    const m = new THREE.Mesh(geo, fill);
    m.position.set(0, 1.48, 13);
    g.add(m);
    addEdges(g, geo);
  }

  /* (e) SHUTTER SPRING 区（前边缘中部小凹槽 10 × 4） */
  {
    const geo = new THREE.BoxGeometry(10, 0.15, 4);
    const m = new THREE.Mesh(geo, fill);
    m.position.set(3, 1.095, 27.5);
    g.add(m);
    addEdges(g, geo);
  }

  return { group: g, fill };
}

/* ================================================================
 *  3.7 SHUTTER（金属滑盖）—— 不透明金属板 + 矩形真镂空
 * ================================================================ */
function createShutter() {
  const g = new THREE.Group();
  /* 不透明金属：无透明、无蓝图幽灵感；永远不参与透明度动画 */
  const metal = new THREE.MeshBasicMaterial({
    color: SHUTTER_COLOR,
    side: THREE.DoubleSide,
    polygonOffset: true,
    polygonOffsetFactor: 1,
    polygonOffsetUnits: 1,
  });

  /* 板面：22(X) × 16(Z) × 1(Y)。
   * 矩形通孔：与 HEAD_CHANNEL 同中心同方位（偏左，孔中心 x=-6）；
   * 名义尺寸 6×14，各边内缩 0.15（6.3×14.3）以避免与上下壳孔壁共面闪烁。
   * 关系：开孔短边(≈6) ∥ 快门长边(X/22)，开孔长边(≈14) ∥ 快门短边(Z/16)。 */
  const s = new THREE.Shape();
  s.moveTo(-11, -8); s.lineTo(11, -8); s.lineTo(11, 8); s.lineTo(-11, 8);
  s.closePath();
  const localCz = HEAD_CHANNEL.cz - SHUTTER_ASSEMBLED.z; // 0.65（快门组原点 Z=21.85）
  addRectHole(s, HEAD_CHANNEL.cx, localCz,
              HEAD_CHANNEL.w + 0.3, HEAD_CHANNEL.d + 0.3);

  const geo = extrudeFlat(s, 1);
  g.add(new THREE.Mesh(geo, metal));
  addEdges(g, geo);
  return { group: g, fill: null };
}

/* ================================================================
 *  3.7 WRITE PROTECT TAB（防写入滑块，3 × 2 × 3，略内缩防共面）
 * ================================================================ */
function createWriteProtectTab() {
  const g = new THREE.Group();
  const fill = fillMaterial();
  const geo = new THREE.BoxGeometry(2.9, 2, 2.9);
  g.add(new THREE.Mesh(geo, fill));
  addEdges(g, geo);
  return { group: g, fill };
}

/* ================================================================
 *  场景组装（初始全部位于 assembledY → 完整软盘外观）
 * ================================================================ */
const scene = new THREE.Scene();

const topShell    = createTopShell();
const linerUp     = createDustLiner();
const hub         = createHub();
const disk        = createDisk();
const linerDn     = createDustLiner();
const bottomShell = createBottomShell();
const shutter     = createShutter();
const tab         = createWriteProtectTab();

/* === ANIMATION: setupParts —— 收集所有可动部件及起止位置/透明度 === */
/* 数组顺序 = 爆炸错峰顺序（自上而下，每项延迟 80ms） */
const parts = [
  { group: topShell.group,    from: V3(0, 1.5, 0),    to: V3(0, 45, 0),
    mats: [topShell.fill],    oFrom: 1, oTo: FILL_EXPLODED_OPACITY },
  { group: linerUp.group,     from: V3(0, 1, 0),      to: V3(0, 30, 0),
    mats: [linerUp.fill],     oFrom: 1, oTo: FILL_EXPLODED_OPACITY },
  { group: hub.group,         from: V3(0, 0.7, 0),    to: V3(0, 18, 0),
    mats: [hub.fill],         oFrom: 1, oTo: FILL_EXPLODED_OPACITY },
  { group: disk.group,        from: V3(0, 0.5, 0),    to: V3(0, 15, 0),
    mats: [disk.fill],        oFrom: 1, oTo: DISK_EXPLODED_OPACITY },
  { group: linerDn.group,     from: V3(0, 0, 0),      to: V3(0, 0, 0),
    mats: [linerDn.fill],     oFrom: 1, oTo: FILL_EXPLODED_OPACITY },
  { group: bottomShell.group, from: V3(0, -1.5, 0),   to: V3(0, -15, 0),
    mats: [bottomShell.fill], oFrom: 1, oTo: FILL_EXPLODED_OPACITY },
  /* 快门：无透明度动画（保持不透明），仅整体位移 */
  { group: shutter.group,     from: SHUTTER_ASSEMBLED, to: SHUTTER_EXPLODED,
    mats: [],                 oFrom: 1, oTo: 1 },
  { group: tab.group,         from: TAB_ASSEMBLED, to: TAB_EXPLODED,
    mats: [tab.fill],         oFrom: 1, oTo: FILL_EXPLODED_OPACITY },
];
parts.forEach((p) => {
  p.group.position.copy(p.from);          // 初始合体
  scene.add(p.group);
});

/* ================================================================
 *  垂直虚线（4 条切角位）与斜向虚线（快门 / 防写滑块）
 * ================================================================ */
function makeDashedLine(pts) {
  const geo = new THREE.BufferGeometry().setFromPoints(pts.map((p) => p.clone()));
  const mat = new THREE.LineDashedMaterial({
    color: BLUEPRINT_BLUE, dashSize: 2.2, gapSize: 1.6,
    transparent: true, opacity: 0,
  });
  const line = new THREE.Line(geo, mat);
  line.computeLineDistances();           // 必须调用，虚线才生效
  line.visible = false;
  scene.add(line);
  return line;
}
const dashedLines = [
  makeDashedLine([V3(-27, -16, -27), V3(-27, 46, -27)]),   // 四角垂直虚线
  makeDashedLine([V3(27, -16, -27), V3(27, 46, -27)]),
  makeDashedLine([V3(-27, -16, 27), V3(-27, 46, 27)]),
  makeDashedLine([V3(27, -16, 27), V3(27, 46, 27)]),
  makeDashedLine([SHUTTER_EXPLODED.clone(), SHUTTER_ASSEMBLED.clone()]),  // 快门 → 下壳槽位
  makeDashedLine([TAB_EXPLODED.clone(), TAB_ASSEMBLED.clone()]),          // 防写滑块 → 凹口
];

/* ================================================================
 *  文字标注（CSS2D）+ 引线
 * ================================================================ */
function makeLabel(text, parent, pos, leaderFrom) {
  const el = document.createElement('div');
  el.className = 'floppy-label';
  el.textContent = text;
  const obj = new CSS2DObject(el);
  obj.position.set(pos[0], pos[1], pos[2]);
  obj.visible = false;                     // 初始隐藏
  parent.add(obj);

  const lGeo = new THREE.BufferGeometry().setFromPoints([
    V3(leaderFrom[0], leaderFrom[1], leaderFrom[2]),
    V3(pos[0], pos[1], pos[2]),
  ]);
  const lMat = new THREE.LineBasicMaterial({
    color: BLUEPRINT_BLUE, transparent: true, opacity: 0,
  });
  const line = new THREE.Line(lGeo, lMat);
  line.visible = false;
  parent.add(line);
  return { obj, line };
}

/* 数组顺序 = 标注淡入顺序（自上而下，间隔 60ms） */
const LABELS_SPEC = [
  { text: 'TOP SHELL',           part: topShell,    pos: [44, 3, 18],    from: [28, 1.2, 10] },
  { text: 'HD NOTCH',            part: topShell,    pos: [-46, 3, -36],  from: [-25.5, 1.2, -25.5] },
  { text: 'DUST LINER (UPPER)',  part: linerUp,     pos: [40, 1, 10],    from: [22, 0.2, 6] },
  { text: 'HUB',                 part: hub,         pos: [16, 1, 18],    from: [3.5, 0.4, 3.5] },
  { text: 'MAGNETIC DISK',       part: disk,        pos: [-40, 1, -16],  from: [-15.5, 0.2, -15.5] },
  { text: 'DUST LINER (LOWER)',  part: linerDn,     pos: [40, 1, 10],    from: [22, 0.2, 6] },
  { text: 'BOTTOM SHELL',        part: bottomShell, pos: [44, 3, 18],    from: [28, 1.2, 10] },
  { text: 'LIFTER',              part: bottomShell, pos: [-18, 3, 16],   from: [0, 2.2, 13] },
  { text: 'SHUTTER SPRING',      part: bottomShell, pos: [14, 2, 36],    from: [3, 1.3, 27.5] },
  { text: 'WRITE PROTECT NOTCH', part: bottomShell, pos: [46, 2, -34],   from: [25.5, 1.2, -25.5] },
  { text: 'SHUTTER',             part: shutter,     pos: [-22, 2, 10],   from: [-10.5, 0.6, 7.5] },
  { text: 'WRITE PROTECT TAB',   part: tab,         pos: [-2, 2, -18],   from: [0, 1.2, 0] },
];
const LABELS = LABELS_SPEC.map((s) =>
  makeLabel(s.text, s.part.group, s.pos, s.from)
);

/* ================================================================
 *  ANIMATION：状态机 / 透明度补间 / 触发
 * ================================================================ */
const TOTAL = 3.0;                 // 爆炸总时长约 3 秒
const STAGGER = 0.08;              // 部件错峰 80ms
const COLLAPSE_HOLD = 0.35;        // 收回前：标注淡出等待

let animState = 'assembled';       // 'assembled' | 'exploding' | 'exploded' | 'collapsing'
let t = 0;                         // 0..TOTAL 动画进度
let collapseHold = 0;
let labelTimer = -1;               // >=0 时计时（exploded 标注时间轴）
let dashesShown = false;
let shownLabels = 0;

/* 通用材质透明度补间（虚线、引线共用，easeInOutCubic） */
const tweens = new Map();
function tweenTo(mat, to, dur) {
  tweens.set(mat, { from: mat.opacity, to, t: 0, dur });
}
function updateTweens(dt) {
  for (const [mat, tw] of [...tweens]) {
    tw.t += dt;
    const k = Math.min(tw.t / tw.dur, 1);
    mat.opacity = tw.from + (tw.to - tw.from) * easeInOutCubic(k);
    if (k >= 1) tweens.delete(mat);
  }
}

/* 用统一 progress 推进所有部件：位置 lerp + 透明度 lerp（错峰共用同一 k） */
function applyParts(progress01) {
  parts.forEach((p, i) => {
    const delay = i * STAGGER;
    const local = (progress01 * TOTAL - delay) / (TOTAL - delay);
    const k = easeInOutCubic(local);
    p.group.position.lerpVectors(p.from, p.to, k);
    for (const m of p.mats) {
      m.opacity = p.oFrom + (p.oTo - p.oFrom) * k;
    }
  });
}

/* === ANIMATION: explode / collapse 触发 === */
function triggerExplode() {
  animState = 'exploding';
  hintEl.style.opacity = '0';       // 提示淡出
}
function triggerCollapse() {
  animState = 'collapsing';
  collapseHold = COLLAPSE_HOLD;
  hideLabels();
}

/* 标注淡入（exploded 后：0.2s 虚线 → 0.4s 起标签逐个 60ms） */
function showLabels() {
  labelTimer = 0;
  dashesShown = false;
  shownLabels = 0;
}
function hideLabels() {
  labelTimer = -1;
  dashesShown = false;
  shownLabels = 0;
  LABELS.forEach((L) => {
    L.obj.el.style.opacity = '0';               // DOM CSS 过渡淡出
    tweenTo(L.line.material, 0, 0.3);           // 引线同步淡出
  });
  dashedLines.forEach((d) => tweenTo(d.material, 0, 0.3));
}

/* === ANIMATION: 每帧推进 === */
function updateAnimation(dt) {
  if (animState === 'exploding') {
    t += dt;
    if (t >= TOTAL) {
      t = TOTAL;
      animState = 'exploded';
      showLabels();
    }
    applyParts(t / TOTAL);
  } else if (animState === 'collapsing') {
    if (collapseHold > 0) {
      collapseHold -= dt;                        // 先等标注淡出
    } else {
      t -= dt;
      if (t <= 0) {
        t = 0;
        animState = 'assembled';
        hintEl.style.opacity = '1';              // 提示淡回
      }
      applyParts(t / TOTAL);
    }
  }

  /* exploded 状态的标注时间轴 */
  if (animState === 'exploded' && labelTimer >= 0) {
    labelTimer += dt;
    if (labelTimer >= 0.2 && !dashesShown) {
      dashesShown = true;
      dashedLines.forEach((d) => {
        d.visible = true;
        tweenTo(d.material, 1, 0.5);             // 虚线 opacity 0→1
      });
    }
    if (labelTimer >= 0.4 && shownLabels < LABELS.length) {
      const idx = Math.min(LABELS.length - 1,
        Math.floor((labelTimer - 0.4) / 0.06));
      for (let i = shownLabels; i <= idx; i++) {
        const L = LABELS[i];
        L.obj.visible = true;
        L.obj.el.style.opacity = '1';            // CSS 过渡自动淡入
        tweenTo(L.line.material, 1, 0.4);        // 引线同步淡入
      }
      shownLabels = idx + 1;
    }
  }

  updateTweens(dt);
}

/* 空格切换方向；动画进行中忽略 */
window.addEventListener('keydown', (e) => {
  if (e.code === 'Space') {
    e.preventDefault();
    if (e.repeat) return;
    if (animState === 'assembled') triggerExplode();
    else if (animState === 'exploded') triggerCollapse();
  }
});

/* ================================================================
 *  交互 — OrbitControls（正交相机：minZoom/maxZoom 限制滚轮缩放）
 * ================================================================ */
function setupControls() {
  const controls = new OrbitControls(camera, renderer.domElement);
  controls.target.set(0, 0, 0);
  controls.enableRotate = true;
  controls.enablePan = true;
  controls.enableZoom = true;                       // 滚轮缩放可用
  controls.enableDamping = true;
  /* 显式按键行为：左键旋转 / 中键 Dolly / 右键平移（滚轮始终可用） */
  controls.mouseButtons = {
    LEFT: THREE.MOUSE.ROTATE,
    MIDDLE: THREE.MOUSE.DOLLY,
    RIGHT: THREE.MOUSE.PAN,
  };
  controls.minZoom = 0.55;                          // 正交相机缩放范围
  controls.maxZoom = 2.4;
  /* 平移范围钳制，避免把软盘拖出画面过多 */
  controls.addEventListener('change', () => {
    controls.target.x = THREE.MathUtils.clamp(controls.target.x, -60, 60);
    controls.target.y = THREE.MathUtils.clamp(controls.target.y, -35, 70);
    controls.target.z = THREE.MathUtils.clamp(controls.target.z, -60, 60);
  });
  return controls;
}
const controls = setupControls();

/* 屏蔽浏览器右键菜单，保证右键平移 */
renderer.domElement.addEventListener('contextmenu', (e) => e.preventDefault());

/* ================================================================
 *  主循环
 * ================================================================ */
const hintEl = document.getElementById('hint');
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const dt = Math.min(clock.getDelta(), 0.1);
  controls.update();
  updateAnimation(dt);
  renderer.render(scene, camera);
  cssRenderer.render(scene, camera);
}
animate();

/* ================================================================
 *  快门与开孔自检（逐条确认）
 *  1. SHUTTER 本体为不透明金属：MeshBasicMaterial 0x4A5568，
 *     transparent=false，不进入 parts[].mats，任何状态下 opacity 恒为 1
 *     → 无半透明幽灵面。✓
 *  2. SHUTTER 为矩形真镂空（Shape + holes 实现，非贴线框）；
 *     偏左：孔中心 x=-6（板面中心 x=0 左侧 6 单位）；
 *     开孔短边(6) ∥ 快门长边(X/22)，长边(14) ∥ 快门短边(Z/16)
 *     → 开孔长轴 ⊥ 快门长轴，呈横置条带。✓
 *  3. TOP SHELL (d) 与 BOTTOM SHELL (g) 与 SHUTTER 三处孔洞全部由
 *     HEAD_CHANNEL 常量（cx=-6, cz=22.5, w=6, d=14）生成，组装态
 *     （快门位于 (0,-1.5,21.85)）三孔同轴对齐，形成连续磁头通道。✓
 * ================================================================ */
</script>
</body>
</html>
```

直接双击打开即可运行：初始为完整合体的软盘（全部不透明线框 + 唯一可见的金属快门槽孔通道），按**空格**开始 3 秒错峰爆炸 → 展开后 0.2s 出现虚线、再 0.2s 后标注自上而下逐个淡入；再按空格收回。左键旋转、滚轮缩放、右键平移（已屏蔽右键菜单）。
